  listItems.forEach(item => {
    const titleEl = item.querySelector('.sku-title, .sku-header');
    const priceEl = item.querySelector('.priceView-customer-price span, .priceView-hero-price span');
    const modelEl = item.querySelector('.sku-model, .sku-value');
    if (titleEl) {
      items.push({
        title: titleEl.textContent?.trim(),
        price: priceEl ? priceEl.textContent?.trim() : null,
        model: modelEl ? modelEl.textContent?.trim() : null
      });
    }
  });
  return items;
});

