const tabId = 248688717;
const items = await browserjs(tabId, () => {
  // Let's find all list items in the main results list
  const results = [];
  const headings = document.querySelectorAll('main h3, main .sku-title, main [data-testid="item-title"]');
  headings.forEach(h => {
    const text = h.textContent?.trim();
    // find containing card
    let parent = h.parentElement;
    while (parent && parent.tagName !== 'LI' && !parent.classList.contains('sku-item')) {
      parent = parent.parentElement;
    }
    const cardText = parent ? parent.innerText : '';
    results.push({
      title: text,
      fullText: cardText
    });
  });
  return results;
});

